/**
 * Fixture data for diff-detector and themed-picker tests.
 *
 * These types are intentionally inlined here so the fixture file is
 * self-contained and can be reviewed in isolation. The shape mirrors
 * what `pipeline/src/types.ts` is expected to export; if the real
 * implementation diverges, structural typing will surface the
 * mismatch at the import sites in the test files.
 *
 * Each `librariesV2[i]` corresponds 1:1 with `arduinoIndexEntries[i]`
 * so diff-detector tests can simulate a sync against the upstream index.
 */

export interface ArduinoIndexEntry {
  readonly name: string;
  readonly version: string;
  readonly author: string;
  readonly maintainer: string;
  readonly sentence: string;
  readonly paragraph: string;
  readonly category: string;
  readonly url: string;
  readonly repository: string;
  readonly architectures: string;
  readonly types: string;
  readonly website?: string;
  readonly email?: string;
}

export interface LibraryVersionHistoryEntry {
  readonly version: string;
  readonly date: string;
}

export interface Library {
  readonly name: string;
  readonly version: string;
  readonly author: string;
  readonly maintainer: string;
  readonly sentence: string;
  readonly paragraph: string;
  readonly category: string;
  readonly architectures: string;
  readonly url: string;
  readonly repository_name: string;
  readonly repository_url: string;
  readonly depends: string;
  readonly includes: string;
  readonly precompiled: string;
  readonly dot_a_linkage: string;
  readonly properties: Readonly<Record<string, string>>;
  readonly processed_at: string;
  readonly enhanced_at?: string;
  readonly enhancement_date?: string;
  readonly github_stars?: number;
  readonly github_forks?: number;
  readonly github_updated_at?: string;
  readonly github_created_at?: string;
  readonly github_pushed_at?: string;
  readonly github_description?: string;
  readonly github_language?: string;
  readonly github_size?: number;
  readonly github_size_kb?: number;
  readonly github_default_branch?: string;
  readonly github_topics?: string;
  readonly github_etag?: string;
  readonly github_fetched_at?: string;
  readonly version_history?: readonly LibraryVersionHistoryEntry[];
}

